('eed03d1b-5dcf-5fab-9d19-9ac514b91e66', 'Single Leg Glute Bridge', 'legs', 'hip_dominant', 'calisthenics', ARRAY['Glutes']::text[], ARRAY['Hamstrings','Core']::text[], ARRAY['bodyweight']::text[], 'bodyweight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Lie on your back, one foot planted, the other leg extended','Drive through the planted heel until the hips are level with the knee and shoulder','Squeeze the glute hard at the top for a full second','Keep the hips square. Do not let the free side drop.']::text[], ARRAY['Letting the free hip sag, which hides the weak side','Pushing through the toes instead of the heel','Arching the lower back at the top instead of squeezing the glute']::text[], 3, '10-15', 60, '', true, false, NULL, now()),
